/* From Uiverse.io by ozgeozkaraa01 - Tags: button, #button */
.__UIV_SCOPE__ button {
  border: none;
  border-radius: 1rem;
  transition: all 0.5s linear;
  padding: 1.2em;
  background-color: #ACB1D6;
}

.__UIV_SCOPE__ .tooltip {
  position: relative;
  display: inline-block;
}

.__UIV_SCOPE__ .tooltip .tooltiptext {
  visibility: hidden;
  background-color: #AAAAAA;
  color: white;
  border-radius: 10px;
  padding: 5px;
  position: absolute;
  z-index: 1;
  left: 62px;
  width: 60px;
}

.__UIV_SCOPE__ .tooltip:hover .tooltiptext {
  visibility: visible;
}
